-- Code generated by factory from specs/sales/list-store-prices-by-prefix/spec.yaml. DO NOT EDIT.

-- name: ListStorePricesByPrefix :many
SELECT t2.product_code, t2.valid_from, t2.valid_to, t2.price
FROM (
    SELECT t1.product_code AS product_code, t1.valid_from AS valid_from, t1.valid_to AS valid_to, t1.price AS price
    FROM store_prices AS t1
    WHERE (t1.store_code = sqlc.arg(store_code)::int4)
      AND ((sqlc.narg(product_prefix)::text IS NULL) OR (t1.product_code LIKE replace(replace(replace(sqlc.narg(product_prefix)::text, '\', '\\'), '%', '\%'), '_', '\_') || '%'))
) AS t2
ORDER BY t2.product_code COLLATE "C", t2.valid_from DESC
LIMIT 201;
